void* task(void* arg) {
    int data = *(int*)arg;
    return (void*)(long)(data + 1);
}

pthread_t tid;
int input = 5;
void* status;

// Create and start thread
pthread_create(&tid, NULL, task, &input);

// Wait for termination and retrieve result
pthread_join(tid, &status);
// int result = (int)(long)status;

pthread_mutex_t mtx;
int counter = 0;

// Protect shared resource access
void increment_safe() {
    pthread_mutex_lock(&mtx);
    counter++;
    pthread_mutex_unlock(&mtx);
}

pthread_cond_t cv;
int processed_flag = 0;

// Waiting for a condition
void consumer_wait() {
    pthread_mutex_lock(&mtx);
    while (!processed_flag) {
        pthread_cond_wait(&cv, &mtx);
    }
    pthread_mutex_unlock(&mtx);
}

// Signaling the condition
void producer_signal() {
    pthread_mutex_lock(&mtx);
    processed_flag = 1;
    pthread_cond_signal(&cv);
    pthread_mutex_unlock(&mtx);
}

